node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {createWorkspace} from './src/workspace.js';
import {createDraftStore} from './src/draft-store.js';
import {createReceiptArchive} from './src/receipt-archive.js';
const jobs = new Map(); let serial=0;
const timers={schedule(fn,delay){assert.equal(delay,120); const id=++serial;jobs.set(id,fn);return id},cancel(id){jobs.delete(id)}};
const tick=()=>{for(const [id,fn] of [...jobs]){jobs.delete(id);fn()}};
const store=createDraftStore(); const archive=createReceiptArchive(); const docs=[],statuses=[],notices=[];
let workspace=createWorkspace({store,archive,timers,renderDocument:x=>docs.push(x),renderStatus:x=>statuses.push(x),renderSubmission:x=>notices.push(x)});
workspace.open('a'); workspace.edit('one');workspace.edit('two');assert.equal(store.read('a'),'');tick();assert.equal(store.read('a'),'two');assert.equal(statuses.length,1);
workspace.edit('three');tick();assert.equal(store.read('a'),'three');assert.equal(statuses.length,2);
workspace.edit('four');workspace.close();assert.equal(store.read('a'),'four');assert.equal(jobs.size,0);
workspace.open('a');assert.equal(docs.at(-1).text,'four');workspace.edit('five');const receipt=workspace.submit();assert.deepEqual(receipt,{id:'a',text:'five'});assert.equal(store.read('a'),'five');assert.equal(notices.at(-1),receipt);
workspace.edit('six');workspace.open('b');assert.equal(store.read('a'),'six');assert.equal(statuses.length,4);
workspace.dispose();
console.log('controlled timer lifecycle checks passed');
EOF

node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {createWorkspace} from './src/workspace.js';
import {createDraftStore} from './src/draft-store.js';
import {createReceiptArchive} from './src/receipt-archive.js';
function setup(onSaved=()=>{}) { const jobs=new Map();let n=0;const timers={schedule(fn,delay){assert.equal(delay,120);const id=++n;jobs.set(id,fn);return id},cancel(id){jobs.delete(id)}};const tick=()=>{for(const [id,fn] of [...jobs]){jobs.delete(id);fn()}};const store=createDraftStore(),archive=createReceiptArchive(),docs=[],statuses=[],notices=[];const api=createWorkspace({store,archive,timers,renderDocument:x=>docs.push(x),renderStatus:x=>statuses.push(x),renderSubmission:x=>notices.push(x),onSaved});return {api,store,archive,docs,statuses,notices,jobs,tick};}
let x=setup();x.api.open('a');x.api.edit('one');x.api.edit('two');assert.equal(x.store.read('a'),'');x.tick();assert.equal(x.store.read('a'),'two');assert.equal(x.statuses.length,1);x.api.edit('three');x.tick();assert.equal(x.store.read('a'),'three');x.api.edit('four');x.api.close();assert.equal(x.store.read('a'),'four');assert.equal(x.jobs.size,0);x.api.open('a');assert.equal(x.docs.at(-1).text,'four');x.api.edit('five');assert.deepEqual(x.api.submit(),{id:'a',text:'five'});assert.equal(x.store.read('a'),'five');assert.deepEqual(x.notices.at(-1),{id:'a',text:'five'});x.api.edit('six');x.api.open('b');assert.equal(x.store.read('a'),'six');assert.equal(x.statuses.length,3);
let once=false;x=setup((event,api)=>{if(!once){once=true;api.open('b')}});x.api.open('a');x.api.edit('draft');x.api.close();assert.equal(x.store.read('a'),'draft');assert.equal(x.docs.at(-1).id,'b');
once=false;x=setup((event,api)=>{if(!once){once=true;api.open('b')}});x.api.open('a');x.api.edit('submitted');const receipt=x.api.submit();assert.deepEqual(receipt,{id:'a',text:'submitted'});assert.deepEqual(x.archive.list(),[{id:'a',text:'submitted'}]);assert.equal(x.notices.at(-1),null);assert.equal(x.docs.at(-1).id,'b');
console.log('controlled timer and reentry checks passed');
EOF
